"fm1studio/x0x_studio.c": String.raw`/* SPDX-License-Identifier: GPL-3.0-only */
/* Added for FM-1 Studio, not a file of X0X.
 *
 * X0X's own browser build, web/emu/x0x_web.c, is host/x0x_host.c (the whole app on a simulated FM-1)
 * with the functions that X0X's page calls. Most of them are the functions of the web_ interface that
 * the audio worklet of FM-1 Studio calls. This file includes it, and gives the others: the screen and
 * the count of its draws, the clock, MIDI input, the MASTER pot in the range of FM-1 Studio, and the
 * LEDs of the buttons, with PLAY's two LEDs and the glow, as plat_leds() of firmware/src/app/plat_fm1.c
 * lights them on the FM-1. The numbers of the buttons and encoders, and the screen, are as in Felucca's
 * emulator ("web" of fm1project.json). */
#define web_master x0x_web_master   /* X0X's takes 0 to 4096: the web_master below takes 0 to 1023 */
#include "../web/emu/x0x_web.c"
#undef web_master

#define EXPORT __attribute__((used, visibility("default")))

/* RGB565, the two bytes of each pixel swapped, as the panel takes them (gfx.c) */
EXPORT uint16_t *web_screen(void) { return fb; }
EXPORT uint32_t web_screen_draws(void) { return blits; }

/* The time of the device in milliseconds: run_ms() moves it while web_render() makes sound */
EXPORT uint32_t web_now_ms(void) { return now_ms; }

/* FM-1 Studio gives the MASTER pot as 0 to 1023, X0X takes 0 to 4096 */
EXPORT void web_master(uint32_t v) { x0x_web_master(v >= 1023u ? 4096u : v * 4096u / 1023u); }

/* A MIDI message into the queue that plat_midi_in() of x0x_host.c reads, as a USB-MIDI packet of cable 0:
 * byte 0 the code index (the high half of the status), then the status and the two data bytes. A
 * message that does not fit is lost. */
EXPORT void web_midi(uint32_t status, uint32_t d1, uint32_t d2)
{
    if (mi_w - mi_r >= MQ)
        return;
    min_q[mi_w++ % MQ] = (status >> 4 & 0x0Fu) | (status & 0xFFu) << 8 | (d1 & 0x7Fu) << 16 | (d2 & 0x7Fu) << 24;
}

/* The LEDs of the buttons, one bit for each in X0X's numbering (B_FX ... B_OCTUP of plat.h), with bit 14
 * for PLAY's green LED and PLAY's own bit for its red one. On the FM-1, PLAY lights its green LED, and
 * its red one while recording (plat_play_red(ui.rec) in ui.c). With the setting of the key LEDs that
 * makes them glow (plat_glow), each button that is not lit glows. */
#define WEB_PLAY_GREEN 14u
static uint32_t web_play(uint32_t bits)
{
    if (!ui.rec && (bits >> B_PLAY & 1u))
        bits = (bits & ~(1u << B_PLAY)) | 1u << WEB_PLAY_GREEN;
    return bits;
}
EXPORT uint32_t web_leds_buttons(void) { return web_play(lit_btn); }
EXPORT uint32_t web_dim_buttons(void) { return glow_on ? web_play(((1u << NB) - 1u) & ~lit_btn) : 0u; }
`,
